const r = $input.first().json;
const exec = r.execution ?? null;
const trig = r.trigger ?? null;

const workflowName = r.workflow?.name ?? 'unknown workflow';
const workflowId = r.workflow?.id ?? null;
const executionId = exec?.id ?? null;
const executionUrl = exec?.url ?? null;
const executionMode = exec?.mode ?? trig?.mode ?? null;
const retryOf = exec?.retryOf ?? null;
// lastNodeExecuted (a plain node-name string) is n8n's documented,
// always-present way to know which node failed for a normal
// (non-trigger-node) error — execution.error has no .node field.
const failedNodeName = exec?.lastNodeExecuted ?? trig?.error?.node ?? null;
const errorMessage = exec?.error?.message
  ?? trig?.error?.cause?.message
  ?? trig?.error?.context?.message
  ?? trig?.error?.name
  ?? 'No error message provided by n8n';
const timestamp = new Date().toISOString();

return [{ json: {
  workflowName,
  workflowId,
  executionId,
  executionUrl,
  executionMode,
  retryOf,
  failedNodeName,
  errorMessage,
  timestamp,
} }];
